('127.565.d.7.B',3,'Illness caused by eating toxins already made by bacteria in food is a food:','["intoxication", "preservation", "fortification", "infection"]'::jsonb,0,'Intoxication.','original'),
('127.565.d.7.B',4,'Illness caused by eating live pathogens that then grow in the body is a food:','["additive", "infection", "allergy", "intoxication"]'::jsonb,1,'Infection.','original'),
